(function(root){
const products=[{id:'chicken',name:'雞肉',pack:'300g',raw:150,buy:54,price:89,yield:3,minutes:20,life:2,initial:20,rawQty:12,rawLife:2,demand:62},{id:'hotpot',name:'火鍋肉片',pack:'200g',buy:90,price:139,life:3,initial:35,demand:48},{id:'japan',name:'日本加工肉品',pack:'250g',buy:180,price:259,life:5,initial:18,demand:22},{id:'beef',name:'源牛',pack:'200g',raw:1500,price:480,yield:4,minutes:35,life:2,initial:0,rawQty:4,rawLife:3,demand:15},{id:'wagyu',name:'黑毛和牛',pack:'200g',raw:2500,price:780,yield:4,minutes:40,life:2,initial:0,rawQty:3,rawLife:3,demand:11},{id:'omi',name:'近江牛',pack:'200g',raw:4000,price:1250,yield:4,minutes:45,life:2,initial:0,rawQty:2,rawLife:3,demand:6}];
function initial(){let b=[];products.forEach(p=>{if(p.initial)b.push({id:p.id,type:'finished',qty:p.initial,cost:p.buy,exp:p.id==='chicken'?1:p.life});if(p.raw)b.push({id:p.id,type:'raw',qty:p.rawQty,cost:p.raw,exp:p.rawLife});});return {day:1,batches:b,history:[]};}
function scenario(day){let weekend=[1,6,7,13,14].includes(day),rain=[3,8,11].includes(day),factor=weekend?1.18:rain?.82:1;return {label:weekend?'假日・來客增加':rain?'雨天・來客偏少':'平日・穩定營業',weather:rain?'雨天 21°C':'晴天 24°C',forecast:products.map(p=>Math.round(p.demand*factor)),actual:products.map((p,i)=>Math.round(p.demand*factor*(.88+((day*17+i*13)%27)/100)))};}
function draft(){return {orders:{chicken:8,chickenPack:20,hotpot:30,japan:7,beef:2,wagyu:1,omi:0},production:{chicken:10,beef:2,wagyu:1,omi:0},staff:{early:1,middle:1,late:1,short:0},sequence:['chicken','beef','wagyu','omi']};}
const shifts={early:{name:'早班',windows:[[9,13],[14,18]]},middle:{name:'中班',windows:[[11,15],[16,20]]},late:{name:'晚班',windows:[[13,17],[18,22]]},short:{name:'短班',windows:[[9,12],[12.5,15]]}};
const hourlyRate=250;
function laborHours(d){return Object.entries(staffing(d)).reduce((total,[id,n])=>total+n*shifts[id].windows.reduce((h,[a,b])=>h+b-a,0),0)}
function repriceResult(r){if(!r)return r;const hours=laborHours(r.draft||{staff:{early:1,middle:0,late:0}});r.labor=hours*hourlyRate;r.laborHours=hours;r.hourlyRate=hourlyRate;r.profit=r.revenue-r.cogs-r.waste-r.labor-1000;return r}
function staffing(d){return {early:0,middle:0,late:0,short:0,...(d.staff||{early:1})}}
function schedule(s,d){
 if(Object.values(staffing(d)).some(n=>!Number.isInteger(n)||n<0||n>5))throw Error('各班人數需為 0～5 的整數');
 let workers=[];
 Object.entries(staffing(d)).forEach(([id,n])=>{for(let i=0;i<n;i++)workers.push({windows:shifts[id].windows.map(w=>w.map(h=>h*60)),next:shifts[id].windows[0][0]*60})});
 let jobs=[];
 function slot(w,earliest,minutes){
  let remaining=minutes,start=null,time=Math.max(w.next,earliest);
  for(let [a,b] of w.windows){time=Math.max(time,a);if(time>=b)continue;if(start===null)start=time;let work=Math.min(remaining,b-time);remaining-=work;time+=work;if(remaining===0)return {start,finish:time};}
  return null;
 }
 d.sequence.forEach(id=>{let p=products.find(p=>p.id===id),old=sum(s.batches,id,'raw');
  for(let i=0;i<(d.production[id]||0);i++){
   let options=workers.map((w,k)=>({k,slot:slot(w,i<old?540:600,p.minutes)})).filter(x=>x.slot).sort((a,b)=>a.slot.finish-b.slot.finish);
   if(!options.length)throw Error('加工無法在所選班別下完成，請增加人數或減少加工量');
   let chosen=options[0];workers[chosen.k].next=chosen.slot.finish;jobs.push({id:jobs.length,p,worker:chosen.k,start:chosen.slot.start/60,finish:chosen.slot.finish/60});
  }
 });
 return jobs;
}
function sum(b,id,type){return b.filter(x=>x.id===id&&x.type===type).reduce((a,x)=>a+x.qty,0)}
function take(b,id,type,qty){let cost=0,got=0;for(let x of b.filter(x=>x.id===id&&x.type===type).sort((a,c)=>a.exp-c.exp)){let n=Math.min(qty-got,x.qty);x.qty-=n;got+=n;cost+=n*x.cost;if(got===qty)break;}return {got,cost};}
function resources(state,d){let cost=0,minutes=0,kg=state.batches.reduce((a,b)=>a+b.qty*(b.type==='raw'?1:products.find(p=>p.id===b.id).pack==='300g'?.3:products.find(p=>p.id===b.id).pack==='250g'?.25:.2),0);products.forEach(p=>{let n=d.orders[p.id]||0;cost+=n*(p.raw||p.buy);kg+=n*(p.raw?1:p.pack==='250g'?.25:.2);if(p.raw)minutes+=(d.production[p.id]||0)*p.minutes});cost+=(d.orders.chickenPack||0)*54;kg+=(d.orders.chickenPack||0)*.3;return {cost,minutes,kg,capacity:laborHours(d)*60,labor:laborHours(d)*hourlyRate};}
function validate(s,d){let e=[],r=resources(s,d);for(let n of [...Object.values(d.orders),...Object.values(d.production)])if(!Number.isInteger(n)||n<0||n>1000)e.push('數量需為 0～1,000 的整數');if(r.cost>30000)e.push('叫貨金額超過 $30,000 預算');if(Object.values(staffing(d)).some(n=>!Number.isInteger(n)||n<0||n>5))e.push('各班人數需為 0～5 的整數');if(r.minutes>r.capacity)e.push('加工超過所排班別的可用工時');if(!e.length){try{schedule(s,d)}catch(err){e.push(err.message)}}if(r.kg>100)e.push('保守冷藏容量檢查超過 100 公斤');products.filter(p=>p.raw).forEach(p=>{if((d.production[p.id]||0)>sum(s.batches,p.id,'raw')+(d.orders[p.id]||0))e.push(p.name+'加工量超過可用原料')});return [...new Set(e)];}
function simulate(s,d){let errors=validate(s,d);if(errors.length)throw Error(errors.join('、'));let batches=JSON.parse(JSON.stringify(s.batches)),sc=scenario(s.day),events=[],logs=[],rows=products.map(p=>({id:p.id,name:p.name,sold:0,lost:0,revenue:0,cogs:0,waste:0,remaining:0}));products.forEach(p=>{let n=d.orders[p.id]||0;if(n)events.push({time:p.raw||p.id==='japan'?10:14,kind:'arrival',p,qty:n,type:p.raw?'raw':'finished',cost:p.raw||p.buy,exp:s.day+(p.raw?p.rawLife:p.life)-1});});if(d.orders.chickenPack)events.push({time:14,kind:'arrival',p:products[0],qty:d.orders.chickenPack,type:'finished',cost:54,exp:s.day+1});schedule(s,d).forEach(job=>{events.push({time:job.start,kind:'start',p:job.p,jobId:job.id});events.push({time:job.finish,kind:'finish',p:job.p,jobId:job.id});});[12,16,21].forEach((time,k)=>events.push({time,kind:'sales',k}));events.sort((a,b)=>a.time-b.time||({arrival:0,finish:1,start:2,sales:3}[a.kind]-{arrival:0,finish:1,start:2,sales:3}[b.kind]));let queues={};for(let ev of events){if(ev.kind==='arrival')batches.push({id:ev.p.id,type:ev.type,qty:ev.qty,cost:ev.cost,exp:ev.exp});if(ev.kind==='start'){let t=take(batches,ev.p.id,'raw',1);if(t.got!==1)throw Error('原料到貨排程錯誤');queues[ev.jobId]=t.cost;}if(ev.kind==='finish'){let cost=queues[ev.jobId];batches.push({id:ev.p.id,type:'finished',qty:ev.p.yield,cost:cost/ev.p.yield,exp:s.day+ev.p.life-1});}if(ev.kind==='sales'){let entries=[];products.forEach((p,i)=>{let demand=ev.k===0?Math.round(sc.actual[i]*.4):ev.k===1?Math.round(sc.actual[i]*.35):sc.actual[i]-Math.round(sc.actual[i]*.4)-Math.round(sc.actual[i]*.35),t=take(batches,p.id,'finished',demand),r=rows[i];r.sold+=t.got;r.lost+=demand-t.got;r.revenue+=t.got*p.price;r.cogs+=t.cost;entries.push({name:p.name,demand,sold:t.got,lost:demand-t.got});});logs.push({time:ev.time,entries});}}
let waste=0;for(let b of batches)if(b.exp<=s.day){let loss=b.qty*b.cost;waste+=loss;rows.find(r=>r.id===b.id).waste+=loss;b.qty=0;}let left=batches.filter(b=>b.qty>0);rows.forEach(r=>r.remaining=sum(left,r.id,'finished'));let revenue=rows.reduce((a,r)=>a+r.revenue,0),cogs=rows.reduce((a,r)=>a+r.cogs,0),profit=revenue-cogs-waste-resources(s,d).labor-1000;return {hourlyRate,laborHours:laborHours(d),labor:resources(s,d).labor,day:s.day,rows,logs,revenue,cogs,waste,profit,missed:rows.reduce((a,r)=>a+r.lost,0),purchase:resources(s,d).cost,inventoryValue:left.reduce((a,b)=>a+b.qty*b.cost,0),batches:left,draft:JSON.parse(JSON.stringify(d))};}
root.Game={hourlyRate,laborHours,repriceResult,shifts,staffing,schedule,products,initial,scenario,draft,sum,resources,validate,simulate};if(typeof module!=='undefined')module.exports=root.Game;
})(typeof window==='undefined'?globalThis:window);
